preConditionHook:
// THE PATTERN'S OWN SLOPE SETS THE EXPECTED BREAKOUT DIRECTION, whatever the
// larger trend is doing. A DOWN-sloping wedge or channel is a bull-flag
// context, so the long pane wants the line through the low pivots sloping
// down; an UP-sloping one is a bear flag, so the short pane wants the line
// through the high pivots sloping up. R18-09 and R23-08 state the same test
// with different emphasis; as a pane filter it is just the slope sign, which
// is why R23-08's override of the engine's trend context is not a problem.
//
// NO DIVISION. The slope through two pivots is
// (newer price - older price) / (bars elapsed), and the denominator is
// loBar3 - loBar1 > 0 whenever three distinct pivots exist, so the SIGN of the
// slope is the sign of the price difference alone. Comparing the prices is
// therefore exact, needs no TLValue anchor pair, cannot divide by zero, and
// keeps the toleranced relational EL applies to prices (el_lt / el_gt).
//
// Only pivots 1 and 3 are used, but all three must exist: with fewer, the
// pattern has no far end. Pivot scan as in ThreePushPattern, inlined; the
// register lists Occurrence 3+ as unmeasured, so the oldest push is found by
// hand. MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the
// pivot bar is AT OR ABOVE the swingStrength OLDER bars and STRICTLY ABOVE the
// swingStrength NEWER bars -- bars-ago indexing, so the newer bars are the
// smaller k and take el_gt / el_lt, the older el_ge / el_le; confirmation lag
// exactly swingStrength bars; candidate offsets
// swingStrength .. lookbackBars - 1, the neighbourhood reaching swingStrength
// bars past the window, so the deepest bar touched is
// lookbackBars - 1 + swingStrength. No early break, matching the twin.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiPx1 = -1.0;
hiPx3 = -1.0;
loPx1 = -1.0;
loPx3 = -1.0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiPx1 = high[j];
        if (nHiPiv == 3) hiPx3 = high[j];
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loPx1 = low[j];
        if (nLoPiv == 3) loPx3 = low[j];
    }
}
slopeDownLows = (nLoPiv == 3) && el_lt(loPx1, loPx3);
slopeUpHighs = (nHiPiv == 3) && el_gt(hiPx1, hiPx3);
